#[derive(Debug, Clone, PartialEq)]
pub struct RecipeUnlockingRequirement {
    pub context: RecipeUnlockingRequirementContext,
    pub ingredients: Option<Vec<RecipeIngredient>>,
}
impl RecipeUnlockingRequirement {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_context = (|| -> Result<_> { Ok(RecipeUnlockingRequirementContext::read(r)?) })()
            .map_err(|e| e.at("RecipeUnlockingRequirement.context"))?;
        let f_ingredients = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some({
                    let n = to_len(read_varint(r)?)?;
                    let mut v = Vec::with_capacity(cap(n, r));
                    for _ in 0..n {
                        v.push(RecipeIngredient::read(r)?);
                    }
                    v
                })
            } else {
                None
            })
        })()
        .map_err(|e| e.at("RecipeUnlockingRequirement.ingredients"))?;
        Ok(Self {
            context: f_context,
            ingredients: f_ingredients,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        self.context.write(w);
        match &self.ingredients {
            Some(x0) => {
                write_bool(w, true);
                write_varint(w, x0.len() as u32);
                for x1 in x0.iter() {
                    x1.write(w);
                }
            }
            None => write_bool(w, false),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
