pub struct PlayerRecord {
    pub r#type: PlayerRecordType,
    pub legacy_type: u8,
    pub content: PlayerRecordContent,
}
impl PlayerRecord {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_type = (|| -> Result<_> { Ok(PlayerRecordType::read(r)?) })()
            .map_err(|e| e.at("PlayerRecord.type"))?;
        let f_legacy_type = (|| -> Result<_> { Ok(read_u8(r)?) })()
            .map_err(|e| e.at("PlayerRecord.legacy_type"))?;
        let f_content = (|| -> Result<_> {
            Ok(if f_type == PlayerRecordType::Add {
                PlayerRecordContent::Add({
                    let f1_uuid = read_uuid(r)?;
                    let f1_entity_unique_id = read_zigzag64(r)?;
                    let f1_username = {
                        let n = to_len(read_varint(r)?)?;
                        read_utf8(r, n)?
                    };
                    let f1_xbox_user_id = {
                        let n = to_len(read_varint(r)?)?;
                        read_utf8(r, n)?
                    };
                    let f1_platform_chat_id = {
                        let n = to_len(read_varint(r)?)?;
                        read_utf8(r, n)?
                    };
                    let f1_build_platform = read_li32(r)?;
                    let f1_skin_data = Skin::read(r)?;
                    let f1_is_teacher = read_bool(r)?;
                    let f1_is_host = read_bool(r)?;
                    let f1_is_subclient = read_bool(r)?;
                    let f1_player_color = read_i32(r)?;
                    PlayerRecordContentAdd {
                        uuid: f1_uuid,
                        entity_unique_id: f1_entity_unique_id,
                        username: f1_username,
                        xbox_user_id: f1_xbox_user_id,
                        platform_chat_id: f1_platform_chat_id,
                        build_platform: f1_build_platform,
                        skin_data: f1_skin_data,
                        is_teacher: f1_is_teacher,
                        is_host: f1_is_host,
                        is_subclient: f1_is_subclient,
                        player_color: f1_player_color,
                    }
                })
            } else if f_type == PlayerRecordType::Remove {
                PlayerRecordContent::Remove({
                    let f1_uuid = read_uuid(r)?;
                    PlayerRecordContentRemove { uuid: f1_uuid }
                })
            } else {
                PlayerRecordContent::Default
            })
        })()
        .map_err(|e| e.at("PlayerRecord.content"))?;
        Ok(Self {
            r#type: f_type,
            legacy_type: f_legacy_type,
            content: f_content,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        self.r#type.write(w);
        write_u8(w, self.legacy_type);
        match &self.content {
            PlayerRecordContent::Add(x0) => {
                let x1 = x0;
                write_uuid(w, &x1.uuid);
                write_zigzag64(w, x1.entity_unique_id);
                {
                    let b = x1.username.as_bytes();
                    write_varint(w, b.len() as u32);
                    write_slice(w, b);
                }
                {
                    let b = x1.xbox_user_id.as_bytes();
                    write_varint(w, b.len() as u32);
                    write_slice(w, b);
                }
                {
                    let b = x1.platform_chat_id.as_bytes();
                    write_varint(w, b.len() as u32);
                    write_slice(w, b);
                }
                write_li32(w, x1.build_platform);
                x1.skin_data.write(w);
                write_bool(w, x1.is_teacher);
                write_bool(w, x1.is_host);
                write_bool(w, x1.is_subclient);
                write_i32(w, x1.player_color);
            }
            PlayerRecordContent::Remove(x0) => {
                let x1 = x0;
                write_uuid(w, &x1.uuid);
            }
            PlayerRecordContent::Default => {}
        }
    }
}

