#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ItemStackRequestCause {
    ChatPublic,
    ChatWhisper,
    SignText,
    AnvilText,
    BookAndQuillText,
    CommandBlockText,
    BlockActorDataText,
    JoinEventText,
    LeaveEventText,
    SlashCommandChat,
    CartographyText,
    KickCommand,
    TitleCommand,
    SummonCommand,
    Unknown(i64),
}
impl ItemStackRequestCause {
    pub fn from_raw(v: i64) -> Self {
        match v {
            0 => Self::ChatPublic,
            1 => Self::ChatWhisper,
            2 => Self::SignText,
            3 => Self::AnvilText,
            4 => Self::BookAndQuillText,
            5 => Self::CommandBlockText,
            6 => Self::BlockActorDataText,
            7 => Self::JoinEventText,
            8 => Self::LeaveEventText,
            9 => Self::SlashCommandChat,
            10 => Self::CartographyText,
            11 => Self::KickCommand,
            12 => Self::TitleCommand,
            13 => Self::SummonCommand,
            v => Self::Unknown(v),
        }
    }
    pub fn to_raw(self) -> i64 {
        match self {
            Self::ChatPublic => 0,
            Self::ChatWhisper => 1,
            Self::SignText => 2,
            Self::AnvilText => 3,
            Self::BookAndQuillText => 4,
            Self::CommandBlockText => 5,
            Self::BlockActorDataText => 6,
            Self::JoinEventText => 7,
            Self::LeaveEventText => 8,
            Self::SlashCommandChat => 9,
            Self::CartographyText => 10,
            Self::KickCommand => 11,
            Self::TitleCommand => 12,
            Self::SummonCommand => 13,
            Self::Unknown(v) => v,
        }
    }
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let v = Self::from_raw(read_li32(r)? as i64);
        if let Self::Unknown(value) = v {
            crate::strict::note(crate::strict::Leniency::UnknownEnum {
                ty: "ItemStackRequestCause",
                value,
            });
        }
        Ok(v)
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_li32(w, self.to_raw() as i32)
    }
}
